1	// pattern: Imperative Shell
2	//
3	// Gathers: DB pool + firehose via AppState, JSON body { did, password, token }
4	// Processes: validate body → verify account password → consume the single-use email token →
5	//            permanently delete the account (all local data) and emit an `#account` (deleted) frame
6	// Returns: 200 OK (empty) on success; ApiError on failure
7	//
8	// Implements: POST /xrpc/com.atproto.server.deleteAccount
9	//
10	// Unlike deactivate/activate, this endpoint is **not** session-authenticated: the credentials are
11	// the `did` + `password` + `token` in the body (a user must be able to delete an account they can
12	// no longer log a session into). The email `token` (minted by `requestAccountDelete`) is the
13	// second factor alongside the account password. The heavy lifting — the multi-table atomic delete,
14	// the firehose frame, and on-disk blob reclamation — lives in `account_delete::purge_account`,
15	// shared with the scheduled-deletion reaper.
16	
17	use axum::{extract::State, http::StatusCode};
18	use serde::Deserialize;
19	
20	use common::{ApiError, ErrorCode};
21	
22	use crate::account_delete::purge_account;
23	use crate::app::AppState;
24	use crate::auth::password::{verify_password, VerifyResult};
25	use crate::auth::token::hash_bearer_token;
26	use crate::db::account_deletion_tokens::consume_account_deletion_token;
27	use crate::db::accounts::account_password_hash;
28	use crate::lexicon::LexiconInput;
29	
30	#[derive(Deserialize)]
31	pub struct DeleteAccountRequest {
32	    did: String,
33	    password: String,
34	    token: String,
35	}
36	
37	/// The uniform error for any credential failure (unknown DID, no password on file, wrong password).
38	/// Kept deliberately generic so the endpoint is not an account-existence or password oracle — the
39	/// email token is bound to the DID, so a legitimate deleter always has all three factors anyway.
40	fn invalid_credentials() -> ApiError {
41	    ApiError::new(ErrorCode::Unauthorized, "invalid credentials")
42	}
43	
44	/// POST /xrpc/com.atproto.server.deleteAccount
45	///
46	/// Permanently deletes the account named by `did` after verifying its `password` and a single-use
47	/// email `token` (from `requestAccountDelete`). On success every local trace of the account is
48	/// removed — repo blocks/blobs (including on-disk blob files), sessions, tokens, handles, DID-doc
49	/// cache, preferences, app passwords, and the account row — and an `#account` frame
50	/// (`active=false`, `status="deleted"`) is broadcast so relays drop the repo. The did:plc identity
51	/// itself is untouched (the wallet owns the rotation key), matching ezpds's wallet-native model.
52	///
53	/// Credential failures return a uniform 401; a malformed body is 400. The 200 no-op applies only
54	/// in the narrow window where the account passed the password + token checks but was purged (by the
55	/// reaper or a racing duplicate request) before this handler's own delete ran — an account that is
56	/// already fully gone before the credential check instead returns 401, since there is no password
57	/// to verify against.
58	pub async fn delete_account_handler(
59	    State(state): State<AppState>,
60	    LexiconInput(payload): LexiconInput<DeleteAccountRequest>,
61	) -> Result<StatusCode, ApiError> {
62	    if payload.did.trim().is_empty()
63	        || payload.password.is_empty()
64	        || payload.token.trim().is_empty()
65	    {
66	        return Err(ApiError::new(
67	            ErrorCode::InvalidRequest,
68	            "did, password, and token are required",
69	        ));
70	    }
71	
72	    // Verify the account password first, so a wrong password never burns the single-use token.
73	    // The lookup is deliberately lifecycle-unfiltered — a deactivated account must still be
74	    // deletable.
75	    match account_password_hash(&state.db, &payload.did).await? {
76	        // No such account, or a mobile account with no main password: nothing to verify against.
77	        None | Some(None) => return Err(invalid_credentials()),
78	        Some(Some(hash)) => match verify_password(&hash, &payload.password) {
79	            VerifyResult::Ok => {}
80	            VerifyResult::WrongPassword => return Err(invalid_credentials()),
81	            VerifyResult::CorruptHash => {
82	                tracing::error!(
83	                    did = %payload.did,
84	                    "stored password_hash is not a valid PHC string; possible DB corruption"
85	                );
86	                return Err(ApiError::new(ErrorCode::InternalError, "internal error"));
87	            }
88	        },
89	    }
90	
91	    // Redeem the email token (atomic single-use, bound to the DID). Password is already verified,
92	    // so consuming here neither leaks account existence nor burns a token on a wrong password.
93	    let token_hash = hash_bearer_token(&payload.token)?;
94	    if !consume_account_deletion_token(&state.db, &payload.did, &token_hash).await? {
95	        return Err(ApiError::new(
96	            ErrorCode::InvalidToken,
97	            "invalid or expired account deletion token",
98	        ));
99	    }
100	
101	    // Both factors check out — permanently delete. A `NotFound` here means the account was deleted
102	    // out from under us between the password check and now (a race with the reaper or a duplicate
103	    // request); treat it as an idempotent success.
104	    purge_account(&state, &payload.did).await?;
105	
106	    Ok(StatusCode::OK)
107	}
