1	// pattern: Imperative Shell
2	//
3	// Gathers: JSON signed proof + destination server DID + current time
4	// Processes: syntax/freshness/local-account checks → signature verification → authoritative
5	//            signing-authority lookup (identity::authority) → atomic active-account recheck +
6	//            nonce consume + full session
7	// Returns: the standard full-access legacy session response
8	
9	use std::time::{SystemTime, UNIX_EPOCH};
10	
11	use axum::{extract::State, http::StatusCode, response::Json};
12	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
13	use common::{ApiError, ErrorCode, SOVEREIGN_TIMESTAMP_WINDOW_SECS};
14	use serde::{Deserialize, Serialize};
15	
16	use crate::app::AppState;
17	use crate::db::accounts::active_local_account_exists;
18	use crate::db::sovereign_session_nonces::insert_nonce_if_absent;
19	use crate::identity::authority::{authorized_signing_keys, AuthorityError};
20	use crate::session_issuer::{issue_session_in_transaction, SessionKind};
21	
22	const NONCE_BYTES: usize = 32;
23	const SIGNATURE_BYTES: usize = 64;
24	const REJECTION_MESSAGE: &str = "sovereign session proof rejected";
25	
26	#[derive(Deserialize)]
27	#[serde(rename_all = "camelCase", deny_unknown_fields)]
28	pub struct SovereignSessionRequest {
29	    did: String,
30	    signing_key: String,
31	    timestamp: i64,
32	    nonce: String,
33	    signature: String,
34	}
35	
36	#[derive(Serialize)]
37	#[serde(rename_all = "camelCase")]
38	pub struct SovereignSessionResponse {
39	    access_jwt: String,
40	    refresh_jwt: String,
41	    handle: String,
42	    did: String,
43	    email: Option<String>,
44	}
45	
46	fn rejected(reason: &'static str, did: &str, signing_key: &str) -> ApiError {
47	    tracing::warn!(
48	        reason,
49	        account_did = %did,
50	        signing_key_did = %signing_key,
51	        "sovereign session proof rejected"
52	    );
53	    ApiError::new(ErrorCode::AuthenticationRequired, REJECTION_MESSAGE)
54	}
55	
56	fn decode_canonical_base64url(value: &str, expected_len: usize) -> Option<Vec<u8>> {
57	    let decoded = URL_SAFE_NO_PAD.decode(value).ok()?;
58	    (decoded.len() == expected_len && URL_SAFE_NO_PAD.encode(&decoded) == value).then_some(decoded)
59	}
60	
61	fn unix_timestamp() -> Result<i64, ApiError> {
62	    let seconds = SystemTime::now()
63	        .duration_since(UNIX_EPOCH)
64	        .map_err(|e| {
65	            tracing::error!(error = %e, "system clock is before Unix epoch");
66	            ApiError::new(
67	                ErrorCode::InternalError,
68	                "failed to verify request timestamp",
69	            )
70	        })?
71	        .as_secs();
72	    i64::try_from(seconds).map_err(|_| {
73	        ApiError::new(
74	            ErrorCode::InternalError,
75	            "system timestamp exceeds supported range",
76	        )
77	    })
78	}
