80	/// Exchange proof from a key in a hosted DID's authoritative current signing authority for a
81	/// standard full-access Custos session.
82	///
83	/// Method-agnostic: a `did:plc` account's authority is its current PLC rotation set (a Custos-held
84	/// rotation key qualifies under exactly the same PLC semantics as any other, granting Custos no
85	/// additional power over an account it already hosts), and a self-hosted `did:web` account's is its
86	/// published `#device` key. See [`crate::identity::authority`] for the policy and its rationale.
87	pub async fn create_sovereign_session(
88	    State(state): State<AppState>,
89	    Json(request): Json<SovereignSessionRequest>,
90	) -> Result<(StatusCode, Json<SovereignSessionResponse>), ApiError> {
91	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
92	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
93	        .ok_or_else(|| {
94	            rejected(
95	                "invalid_signature_encoding",
96	                &request.did,
97	                &request.signing_key,
98	            )
99	        })?;
100	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
101	        return Err(rejected(
102	            "invalid_nonce_encoding",
103	            &request.did,
104	            &request.signing_key,
105	        ));
106	    }
107	    let now = unix_timestamp()?;
108	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
109	        return Err(rejected(
110	            "timestamp_outside_window",
111	            &request.did,
112	            &request.signing_key,
113	        ));
114	    }
115	
116	    // This cheap local gate precedes signature verification and the outbound PLC lookup. Missing
117	    // and every inactive lifecycle state intentionally share one response.
118	    if !active_local_account_exists(&state.db, &request.did).await? {
119	        return Err(rejected(
120	            "account_not_active_local",
121	            &request.did,
122	            &request.signing_key,
123	        ));
124	    }
125	
126	    let server_did = state.config.resolve_server_did();
127	    let envelope = crypto::encode_sovereign_session_envelope(
128	        &server_did,
129	        &request.did,
130	        &request.signing_key,
131	        request.timestamp,
132	        &request.nonce,
133	    );
134	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
135	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature).map_err(|_| {
136	        rejected(
137	            "signature_verification_failed",
138	            &request.did,
139	            &request.signing_key,
140	        )
141	    })?;
142	
143	    // The account's signing authority, read live from its DID method's authoritative source — the
144	    // latest non-nullified PLC audit-log operation, or the published did:web document. The locally
145	    // cached W3C DID document is deliberately never consulted for either method.
146	    let authority = authorized_signing_keys(&state, &request.did)
147	        .await
148	        .map_err(|error| match error {
149	            AuthorityError::Unauthorized(reason) => {
150	                rejected(reason, &request.did, &request.signing_key)
151	            }
152	            AuthorityError::Lookup(err) => err,
153	        })?;
154	    if !authority.authorizes(&request.signing_key) {
155	        return Err(rejected(
156	            "signing_key_not_authorized",
157	            &request.did,
158	            &request.signing_key,
159	        ));
160	    }
161	
162	    // The lifecycle recheck, one-time nonce insertion, and both session rows share one SQLite
163	    // transaction. A replay or a concurrent deactivation therefore cannot mint a partial session.
164	    let mut tx = state.db.begin().await.map_err(|e| {
165	        tracing::error!(error = %e, account_did = %request.did, "failed to begin sovereign session transaction");
166	        ApiError::new(ErrorCode::InternalError, "failed to create session")
167	    })?;
168	    if !active_local_account_exists(&mut *tx, &request.did).await? {
169	        return Err(rejected(
170	            "account_became_inactive",
171	            &request.did,
172	            &request.signing_key,
173	        ));
174	    }
175	    if !insert_nonce_if_absent(&mut *tx, &request.did, &request.nonce)
176	        .await
177	        .map_err(|e| {
178	            tracing::error!(error = %e, account_did = %request.did, "failed to consume sovereign nonce");
179	            ApiError::new(ErrorCode::InternalError, "failed to create session")
180	        })?
181	    {
182	        return Err(rejected(
183	            "nonce_replay",
184	            &request.did,
185	            &request.signing_key,
186	        ));
187	    }
188	    let issued =
189	        issue_session_in_transaction(&mut tx, &state, &request.did, &SessionKind::FullAccess)
190	            .await?;
191	    tx.commit().await.map_err(|e| {
192	        tracing::error!(error = %e, account_did = %request.did, "failed to commit sovereign session transaction");
193	        ApiError::new(ErrorCode::InternalError, "failed to create session")
194	    })?;
195	
196	    tracing::info!(
197	        account_did = %request.did,
198	        signing_key_did = %request.signing_key,
199	        authority = %authority.source,
200	        "sovereign full-access session issued"
201	    );
202	    Ok((
203	        StatusCode::OK,
204	        Json(SovereignSessionResponse {
205	            access_jwt: issued.access_jwt,
206	            refresh_jwt: issued.refresh_jwt,
207	            handle: issued.handle,
208	            did: issued.did,
209	            email: issued.email,
210	        }),
211	    ))
212	}
