3	//! Canonical signed envelope for Custos sovereign-session proofs.
4	
5	/// Protocol domain and version. Changing the wire encoding requires a new domain.
6	pub const SOVEREIGN_SESSION_DOMAIN: &str = "org.obsign.custos.sovereign-session.v1";
7	pub const SOVEREIGN_SESSION_METHOD: &str = "POST";
8	pub const SOVEREIGN_SESSION_PATH: &str = "/v1/sessions/sovereign";
9	
10	/// Encode the exact bytes signed by a sovereign-session client.
11	///
12	/// Every value is UTF-8 byte-length-prefixed, so the encoding remains unambiguous even if a
13	/// future identifier syntax admits separators or newlines. Field order is part of version 1:
14	/// domain, audience, method, path, account DID, signing-key DID, timestamp, then nonce.
15	pub fn encode_sovereign_session_envelope(
16	    server_did: &str,
17	    account_did: &str,
18	    signing_key_did: &str,
19	    timestamp: i64,
20	    nonce: &str,
21	) -> Vec<u8> {
22	    let timestamp = timestamp.to_string();
23	    let fields = [
24	        ("domain", SOVEREIGN_SESSION_DOMAIN),
25	        ("aud", server_did),
26	        ("method", SOVEREIGN_SESSION_METHOD),
27	        ("path", SOVEREIGN_SESSION_PATH),
28	        ("did", account_did),
29	        ("key", signing_key_did),
30	        ("timestamp", timestamp.as_str()),
31	        ("nonce", nonce),
32	    ];
33	
34	    let mut encoded = Vec::new();
35	    for (name, value) in fields {
36	        encoded.extend_from_slice(name.as_bytes());
37	        encoded.push(b':');
38	        encoded.extend_from_slice(value.len().to_string().as_bytes());
39	        encoded.push(b':');
40	        encoded.extend_from_slice(value.as_bytes());
41	        encoded.push(b'\n');
42	    }
43	    encoded
44	}
