2	//
3	// The shared "which keys may sign a sovereign proof for this account" lookup, behind the two
4	// passwordless auth surfaces (`POST /v1/sessions/sovereign`, `POST /oauth/authorize/approve`).
5	// Signature verification is already method-agnostic (`crypto::verify_did_key_signature` over a
6	// `did:key:` URI, P-256 and secp256k1), so the authority lookup is the only place a DID method
7	// matters. It lives here rather than in either route because routes may not import one another.
8	//
9	// Both methods resolve their authority **live** from the authoritative source, never from the
10	// `did_documents` cache — for did:plc because `rotationKeys` is authoritative only in the latest
11	// non-nullified audit-log operation, and for did:web because that cache is writable by
12	// `POST /v1/did-web/document`.
13	
14	use common::ApiError;
15	use serde_json::Value;
16	
17	use crate::app::AppState;
18	
19	use super::plc::fetch_current_plc_state;
20	use super::resolution::resolve_web_did_document;
21	
22	/// The set of `did:key:` URIs currently authorized to sign a sovereign proof for an account,
23	/// plus a short description of the authority state they were read from (for the success log).
24	pub struct AuthoritySet {
25	    keys: Vec<String>,
26	    pub source: String,
27	}
28	
29	impl AuthoritySet {
30	    pub fn authorizes(&self, signing_key: &str) -> bool {
31	        self.keys.iter().any(|key| key == signing_key)
32	    }
33	}
34	
35	/// A failed authority lookup, split by who the caller should blame.
36	pub enum AuthorityError {
37	    /// The DID method, document, or policy denies any authority. The caller collapses this into
38	    /// its own opaque rejection — it must never become a distinguishable response.
39	    Unauthorized(&'static str),
40	    /// The authoritative source could not be consulted. Propagated as-is so an upstream outage
41	    /// still fails closed with its own status (a plc.directory 503 stays a 502, not a 401).
42	    Lookup(ApiError),
43	}
44	
45	fn is_plc_did(value: &str) -> bool {
46	    let Some(suffix) = value.strip_prefix("did:plc:") else {
47	        return false;
48	    };
49	    suffix.len() == 24
50	        && suffix
51	            .bytes()
52	            .all(|byte| byte.is_ascii_lowercase() || (b'2'..=b'7').contains(&byte))
53	}
54	
55	/// Resolve the account's current signing authority from its DID method's authoritative source.
56	pub async fn authorized_signing_keys(
57	    state: &AppState,
58	    did: &str,
59	) -> Result<AuthoritySet, AuthorityError> {
60	    if is_plc_did(did) {
61	        plc_authority(state, did).await
62	    } else if did.starts_with("did:web:") {
63	        web_authority(state, did).await
64	    } else {
65	        Err(AuthorityError::Unauthorized("unsupported_did_method"))
66	    }
67	}
