69	/// did:plc — every key in the DID's current `rotationKeys`. A Custos-held rotation key qualifies
70	/// under exactly the same PLC semantics as any other, granting Custos no power over an account it
71	/// already hosts: rewriting the rotation set requires an existing rotation key, and plc.directory
72	/// is external to this server.
73	async fn plc_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
74	    let plc = fetch_current_plc_state(&state.http_client, &state.config.plc_directory_url, did)
75	        .await
76	        .map_err(AuthorityError::Lookup)?;
77	    Ok(AuthoritySet {
78	        keys: plc.rotation_keys,
79	        source: format!("plc:{}", plc.cid),
80	    })
81	}
