83	/// did:web — exactly the document's `{did}#device` verification method, and nothing else.
84	///
85	/// Not "any verificationMethod": `#atproto`'s private key is Custos-held, so a broader set would
86	/// let this server sign its own sovereign envelope for an account it hosts. `#device` alone also
87	/// keeps one rule across both did:web paths — `create_did.rs` already enforces `#device`
88	/// specifically when promoting a new did:web.
89	///
90	/// Gated on self-hosted only. `POST /v1/did-web/document` lets an account rewrite its served
91	/// document under mere session auth, so for a Custos-hosted did:web a stolen session could install
92	/// an attacker `#device` key and bootstrap sovereign sessions — a privilege escalation with no key
93	/// compromise. That route already refuses unless hosting is enabled, so
94	/// `did_web_hosting_enabled_at IS NULL` **is** the condition "no session-authed rewrite is
95	/// possible", with no gap in either direction. Making `#device` immutable across such an edit
96	/// would let this gate be dropped later without redesigning anything.
97	async fn web_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
98	    // Cheap DB gate before the outbound fetch.
99	    if crate::db::dids::did_web_hosting_enabled(&state.db, did)
100	        .await
101	        .map_err(AuthorityError::Lookup)?
102	    {
103	        return Err(AuthorityError::Unauthorized("did_web_hosting_enabled"));
104	    }
105	
106	    let document = resolve_web_did_document(state, did)
107	        .await
108	        .map_err(AuthorityError::Lookup)?;
109	    let device_key = device_verification_key(&document, did)?;
110	    Ok(AuthoritySet {
111	        keys: vec![device_key],
112	        source: "did:web#device".to_string(),
113	    })
114	}
115	
116	/// Extract the document's `#device` key as a `did:key:` URI, matching `create_did.rs`'s predicate
117	/// (`type == "Multikey"`, `controller == did`, exact `{did}#device` id). The difference in shape:
118	/// `create_did.rs` *verifies* a known key by comparing `publicKeyMultibase`, whereas this
119	/// *discovers* it, so it extracts that field instead — rendered as `did:key:{multibase}`, since the
120	/// verification method carries bare multibase while a PLC rotation set stores `did:key:` URIs.
121	///
122	/// More than one `#device`-shaped entry is malformed (duplicate `id` values already violate DID
123	/// Core) and fails closed rather than picking one by array order.
124	fn device_verification_key(document: &Value, did: &str) -> Result<String, AuthorityError> {
125	    let expected_id = format!("{did}#device");
126	    let methods = document
127	        .get("verificationMethod")
128	        .and_then(Value::as_array)
129	        .ok_or(AuthorityError::Unauthorized("no_verification_methods"))?;
130	    let mut matches = methods.iter().filter(|method| {
131	        method.get("id").and_then(Value::as_str) == Some(&expected_id)
132	            && method.get("type").and_then(Value::as_str) == Some("Multikey")
133	            && method.get("controller").and_then(Value::as_str) == Some(did)
134	    });
135	    let Some(method) = matches.next() else {
136	        return Err(AuthorityError::Unauthorized(
137	            "no_device_verification_method",
138	        ));
139	    };
140	    if matches.next().is_some() {
141	        return Err(AuthorityError::Unauthorized(
142	            "duplicate_device_verification_method",
143	        ));
144	    }
145	    let multibase = method
146	        .get("publicKeyMultibase")
147	        .and_then(Value::as_str)
148	        .ok_or(AuthorityError::Unauthorized("device_key_not_multibase"))?;
149	    Ok(format!("did:key:{multibase}"))
150	}
