132	/// Errors from the identity-removal flow.
133	///
134	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE", ... }` to match the other wallet
135	/// error enums (`RecoveryError`, `SessionError`, …). Variants are ordered by the step
136	/// that produces them so the UI can tell what already happened — notably, a
137	/// `PlcDirectoryError`/`RateLimited`/`NetworkError` *after* `InvalidToken` succeeded
138	/// means the PDS account is gone and only the tombstone + wipe remain (resume via
139	/// `tombstone_identity`).
140	#[derive(Debug, Serialize, thiserror::Error)]
141	#[serde(
142	    tag = "code",
143	    rename_all = "SCREAMING_SNAKE_CASE",
144	    rename_all_fields = "camelCase"
145	)]
146	pub enum RemovalError {
147	    /// The identity has no usable session; the UI must run the passwordless
148	    /// `sovereignLogin(did)` unlock before requesting deletion.
149	    #[error("identity needs a passwordless unlock before removal")]
150	    SessionRequired { reason: UnlockReason },
151	    /// `requestAccountDelete` failed (could not mint/send the confirmation code).
152	    #[error("failed to request account deletion: {message}")]
153	    RequestDeleteFailed { message: String },
154	    /// The PDS rejected the account password or the emailed confirmation code.
155	    #[error("invalid password or confirmation code")]
156	    InvalidToken,
157	    /// `deleteAccount` failed for a reason other than bad credentials.
158	    #[error("account deletion failed: {message}")]
159	    AccountDeleteFailed { message: String },
160	    /// The DID's plc.directory audit log could not be fetched/parsed for the tombstone `prev`.
161	    #[error("could not read the identity's PLC log: {message}")]
162	    InvalidAuditLog { message: String },
163	    /// Building or signing the tombstone with the device key failed.
164	    #[error("failed to sign the tombstone: {message}")]
165	    TombstoneSigningFailed { message: String },
166	    /// plc.directory rejected the tombstone. The account is already deleted — retry via
167	    /// `tombstone_identity`.
168	    #[error("plc.directory rejected the tombstone: {message}")]
169	    PlcDirectoryError { message: String },
170	    /// The DID's device key / managed-dids entry is missing.
171	    #[error("identity not found: {message}")]
172	    IdentityNotFound { message: String },
173	    /// The account was deleted and tombstoned, but the local Keychain wipe failed.
174	    #[error("local cleanup failed after removal: {message}")]
175	    LocalWipeFailed { message: String },
176	    /// A server rate-limited a step; the UI can retry after `retryAfter`.
177	    #[error("rate limited")]
178	    RateLimited { retry_after: Option<String> },
179	    /// Transport failure reaching the PDS or plc.directory.
180	    #[error("network error: {message}")]
181	    NetworkError { message: String },
182	}
183	
184	/// The successful result of a removal (or a `tombstone_identity` resume).
185	#[derive(Debug, Serialize, Clone, PartialEq, Eq)]
186	#[serde(rename_all = "camelCase")]
187	pub struct RemovalOutcome {
188	    /// The CID of the submitted did:plc tombstone operation, or `None` when the removed
189	    /// DID has no tombstone leg (a did:web — there is no PLC operation, so there is no CID
190	    /// to report). Reporting the absence is what lets the UI show the did:web epilogue
191	    /// instead of claiming a network-wide retirement that did not happen.
192	    pub tombstone_cid: Option<String>,
193	    /// `true` if the removed DID was the last managed identity — the UI returns to
194	    /// onboarding rather than the identity list.
195	    pub was_last_identity: bool,
196	}
197	
198	/// Map a `deleteAccount` `PdsClientError` onto the removal error surface.
199	///
200	/// A 401 (wrong password) and a 400 `INVALID_TOKEN` (bad/expired confirmation code)
201	/// both collapse to `InvalidToken` — the UI re-prompts for both — while other XRPC
202	/// failures are a distinct `AccountDeleteFailed`.
203	fn map_delete_account_error(e: PdsClientError) -> RemovalError {
204	    match e {
205	        PdsClientError::Unauthorized { .. } => RemovalError::InvalidToken,
206	        PdsClientError::XrpcError { status: 400, .. } => RemovalError::InvalidToken,
207	        PdsClientError::RateLimited { retry_after, .. } => {
208	            RemovalError::RateLimited { retry_after }
209	        }
210	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
211	        other => RemovalError::AccountDeleteFailed {
212	            message: other.to_string(),
213	        },
214	    }
215	}
216	
217	/// Map a `requestAccountDelete` `PdsClientError` onto the removal error surface.
218	fn map_request_delete_error(e: PdsClientError) -> RemovalError {
219	    match e {
220	        PdsClientError::RateLimited { retry_after, .. } => {
221	            RemovalError::RateLimited { retry_after }
222	        }
223	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
224	        other => RemovalError::RequestDeleteFailed {
225	            message: other.to_string(),
226	        },
227	    }
228	}
229	
230	/// Map a `SessionProvider` failure onto the removal error surface.
231	fn map_session_error(e: SessionError) -> RemovalError {
232	    match e {
233	        SessionError::NeedsUnlock { reason } => RemovalError::SessionRequired { reason },
234	        SessionError::IdentityNotFound => RemovalError::IdentityNotFound {
235	            message: "no managed identity for this DID".to_string(),
236	        },
237	        SessionError::RateLimited { retry_after } => RemovalError::RateLimited { retry_after },
238	        SessionError::Offline { message } => RemovalError::NetworkError { message },
239	        other => RemovalError::RequestDeleteFailed {
240	            message: other.to_string(),
241	        },
242	    }
243	}
244	
245	/// Submit the tombstone, then — only if that succeeded — run the local wipe.
246	///
247	/// Split out so the ordering invariant ("the wipe never runs on a submit failure",
248	/// which keeps the device key alive for a `tombstone_identity` retry) is unit-testable
249	/// without a Keychain or a live plc.directory.
250	async fn submit_then_wipe<Submit, Wipe>(submit: Submit, wipe: Wipe) -> Result<(), RemovalError>
251	where
252	    Submit: std::future::Future<Output = Result<(), RemovalError>>,
253	    Wipe: FnOnce() -> Result<(), RemovalError>,
254	{
255	    submit.await?;
256	    wipe()
257	}
258	
259	/// `true` if `did` is a did:plc — the only method with a plc.directory log to tombstone.
260	///
261	/// Every other method (today: did:web) reaches plc.directory only to be 404'd, so the
262	/// tombstone leg is skipped rather than attempted. This is the single place the removal
263	/// flow decides "does this DID have a tombstone", so the command boundary, the resume
264	/// path, and the reported `RemovalOutcome` can never disagree about it.
265	fn has_plc_tombstone(did: &str) -> bool {
266	    did.starts_with("did:plc:")
267	}
268	
269	/// Retire the DID as far as the wallet can, then wipe local Keychain material.
270	///
271	/// The method-aware entry point shared by `confirm_identity_removal` (after the PDS
272	/// account is deleted) and `tombstone_identity` (the resume path, where the account is
273	/// already gone):
274	///   - **did:plc** → build + sign + submit the tombstone, then wipe. Returns the CID.
275	///   - **anything else** (did:web) → wipe only, never touching plc.directory. Returns
276	///     `None`: retiring the DID network-wide means taking its document off the domain,
277	///     which is the operator's action, not the wallet's.
278	async fn retire_and_wipe(
279	    pds_client: &PdsClient,
280	    did: &str,
281	) -> Result<Option<String>, RemovalError> {
282	    if !has_plc_tombstone(did) {
283	        wipe_local(&IdentityStore, did)?;
284	        return Ok(None);
285	    }
286	    tombstone_and_wipe(pds_client, did).await.map(Some)
287	}
288	
289	/// Build + sign + submit the did:plc tombstone, then wipe local Keychain material.
290	///
291	/// did:plc only — reached exclusively through [`retire_and_wipe`], which owns the method
292	/// branch. Returns the tombstone CID on success.
293	async fn tombstone_and_wipe(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
294	    let store = IdentityStore;
295	
296	    // 1. Fetch + parse the audit log and locate the head (newest non-nullified) operation.
297	    let audit_log_json =
298	        pds_client
299	            .fetch_audit_log(did)
300	            .await
301	            .map_err(|e| RemovalError::InvalidAuditLog {
302	                message: format!("failed to fetch audit log: {e}"),
303	            })?;
304	    let audit_log =
305	        crypto::parse_audit_log(&audit_log_json).map_err(|e| RemovalError::InvalidAuditLog {
306	            message: format!("failed to parse audit log: {e}"),
307	        })?;
308	    let head = audit_log
309	        .iter()
310	        .rev()
311	        .find(|e| !e.nullified)
312	        .ok_or_else(|| RemovalError::InvalidAuditLog {
313	            message: "audit log has no non-nullified operation to chain onto".to_string(),
314	        })?;
315	    let head_cid = head.cid.clone();
316	
317	    // Idempotent resume: if the DID is already tombstoned (its head IS a tombstone), the
318	    // submit already landed on plc.directory — only the local wipe remains. Submitting a
319	    // second tombstone would be rejected (a retired DID accepts no further ops), so a resume
320	    // after a wipe-only failure must skip straight to the wipe. This is what makes
321	    // `tombstone_identity` safe to call after a partial success.
322	    let head_is_tombstone =
323	        head.operation.get("type").and_then(|t| t.as_str()) == Some("plc_tombstone");
324	    if head_is_tombstone {
325	        wipe_local(&store, did)?;
326	        return Ok(head_cid);
327	    }
328	
329	    // The tombstone chains onto the head and must be signed by one of the head op's
330	    // `rotationKeys`. Verifying against those (not merely the local device key) is what
331	    // proves the wallet's key is still a *current* rotation key — the exact authorization
332	    // plc.directory will enforce — so a device key that is no longer in the rotation set
333	    // (e.g. after a migrate-away) fails fast locally instead of after the network round trip.
334	    let head_rotation_keys = extract_rotation_keys(&head.operation);
335	    if head_rotation_keys.is_empty() {
336	        return Err(RemovalError::InvalidAuditLog {
337	            message: "head operation has no rotationKeys to authorize the tombstone".to_string(),
338	        });
339	    }
340	
341	    // 2. Obtain the per-DID device-key signing closure (rotationKeys[0]).
342	    let sign = crate::identity_store::per_did_sign_closure(did).map_err(|e| match e {
343	        PerDidSignError::DeviceKeyNotFound { message } => {
344	            RemovalError::IdentityNotFound { message }
345	        }
346	        PerDidSignError::SigningSetupFailed { message } => {
347	            RemovalError::TombstoneSigningFailed { message }
348	        }
349	    })?;
350	
351	    // 3. Build + sign the tombstone (prev = the head CID).
352	    let tombstone = crypto::build_did_plc_tombstone_op(&head_cid, sign).map_err(|e| {
353	        RemovalError::TombstoneSigningFailed {
354	            message: format!("failed to build tombstone: {e}"),
355	        }
356	    })?;
357	
358	    // 3b. Local self-check against the head op's authorized rotation keys (see above).
359	    crypto::verify_plc_tombstone_op(&tombstone.signed_op_json, &head_rotation_keys).map_err(
360	        |e| RemovalError::TombstoneSigningFailed {
361	            message: format!("tombstone self-verification failed: {e}"),
362	        },
363	    )?;
364	
365	    let op_value: serde_json::Value =
366	        serde_json::from_str(&tombstone.signed_op_json).map_err(|e| {
367	            RemovalError::TombstoneSigningFailed {
368	                message: format!("failed to parse signed tombstone JSON: {e}"),
369	            }
370	        })?;
371	
372	    // 4. Submit to plc.directory, THEN (only on success) 5. wipe local material.
373	    //    Every failure in this function is post-delete (the account is already gone when
374	    //    `confirm_identity_removal` calls us), so PLC-submit transport/rate-limit failures
375	    //    fold into `PlcDirectoryError` rather than the bare `NetworkError`/`RateLimited` the
376	    //    deletion stage uses — that keeps the two stages' error codes disjoint, so the UI
377	    //    only enters the tombstone-retry path for genuinely post-delete failures.
378	    let did_owned = did.to_string();
379	    submit_then_wipe(
380	        async {
381	            pds_client
382	                .post_plc_operation(&did_owned, &op_value)
383	                .await
384	                .map_err(|e| RemovalError::PlcDirectoryError {
385	                    message: format!("plc.directory rejected the tombstone: {e}"),
386	                })
387	        },
388	        || wipe_local(&store, &did_owned),
389	    )
390	    .await?;
391	
392	    Ok(tombstone.cid)
393	}
394	
395	/// Extract a PLC operation's `rotationKeys` as typed did:key URIs (empty if absent/malformed).
396	fn extract_rotation_keys(operation: &serde_json::Value) -> Vec<crypto::DidKeyUri> {
397	    operation
398	        .get("rotationKeys")
399	        .and_then(|v| v.as_array())
400	        .map(|arr| {
401	            arr.iter()
402	                .filter_map(|v| v.as_str().map(|s| crypto::DidKeyUri(s.to_string())))
403	                .collect()
404	        })
405	        .unwrap_or_default()
406	}
