408	/// Wipe the DID's local Keychain material. Best-effort and idempotent: a missing
409	/// managed-dids entry (already removed by a prior partial run) is success, not failure.
410	fn wipe_local(store: &IdentityStore, did: &str) -> Result<(), RemovalError> {
411	    match store.remove_identity(did) {
412	        Ok(()) => Ok(()),
413	        Err(crate::identity_store::IdentityStoreError::IdentityNotFound) => Ok(()),
414	        Err(e) => Err(RemovalError::LocalWipeFailed {
415	            message: format!("failed to wipe local identity material: {e}"),
416	        }),
417	    }
418	}
