420	/// `true` if no managed identities remain — the UI returns to onboarding rather than the
421	/// identity list. Shared by the tombstone-completing paths and the local-only forget path.
422	fn no_identities_remain() -> Result<bool, RemovalError> {
423	    IdentityStore
424	        .list_identities()
425	        .map(|ids| ids.is_empty())
426	        .map_err(|e| RemovalError::LocalWipeFailed {
427	            message: format!("failed to re-read managed identities: {e}"),
428	        })
429	}
