440	///
441	/// Obtains a full-access session for `did` (the frontend runs the passwordless unlock
442	/// first if this returns `SessionRequired`) and calls `requestAccountDelete`. The PDS
443	/// emails a 1-hour code to the account address; the user then supplies that code plus
444	/// the account password to `confirm_identity_removal`.
445	#[tauri::command]
446	pub async fn request_identity_removal(
447	    state: tauri::State<'_, crate::oauth::AppState>,
448	    did: String,
449	) -> Result<(), RemovalError> {
450	    let now =
451	        crate::sovereign_session::unix_timestamp().map_err(|_| RemovalError::NetworkError {
452	            message: "system clock is unavailable".to_string(),
453	        })?;
454	    let session = SessionProvider
455	        .full_access_client(state.pds_client(), &IdentityStore, &did, now)
456	        .await
457	        .map_err(map_session_error)?;
458	
459	    crate::pds_client::request_account_delete(&session.client)
460	        .await
461	        .map_err(map_request_delete_error)
