464	/// Tauri command: confirm removal — delete on the PDS, tombstone the DID, wipe locally.
465	///
466	/// `password` is the account password (set during the DID ceremony); `token` is the
467	/// emailed confirmation code. `deleteAccount` is attempted FIRST, so a wrong
468	/// password/code (`InvalidToken`) leaves everything intact and the UI re-prompts. Once
469	/// the account is deleted, `retire_and_wipe` runs the method-appropriate tail: the
470	/// tombstone + wipe for a did:plc, the wipe alone for a did:web.
471	#[tauri::command]
472	pub async fn confirm_identity_removal(
473	    state: tauri::State<'_, crate::oauth::AppState>,
474	    did: String,
475	    password: String,
476	    token: String,
477	) -> Result<RemovalOutcome, RemovalError> {
478	    // The account's PDS base URL comes from its still-present token record (the wipe is
479	    // last). Falling back to live discovery keeps a stale/absent record from stranding
480	    // an otherwise-deletable account.
481	    let pds_url = resolve_pds_url(state.pds_client(), &did).await?;
482	
483	    // 1. Permanently delete the account on the PDS (body-authed; no session needed).
484	    state
485	        .pds_client()
486	        .delete_account(&pds_url, &did, &password, &token)
487	        .await
488	        .map_err(map_delete_account_error)?;
489	
490	    // The account is now permanently gone and the single-use email code is spent — from
491	    // here on, only the tombstone + local wipe remain. Persist a durable marker BEFORE the
492	    // tombstone's network round trip so that if iOS kills/suspends the app mid-tombstone,
493	    // the next launch resumes via `tombstone_identity` rather than the request flow (which
494	    // would fail against the deleted account). A marker-write failure is logged but never
495	    // blocks the removal: the account is already deleted, so aborting here would only strand
496	    // the identity harder.
497	    if let Err(e) = mark_removal_pending(&did) {
498	        tracing::warn!(did = %did, error = %e, "failed to persist pending-removal marker after deleteAccount");
499	    }
500	
501	    // 2 + 3. Retire the DID (tombstone, did:plc only), then wipe local material.
502	    let tombstone_cid = retire_and_wipe(state.pds_client(), &did).await?;
503	    clear_removal_pending_best_effort(&did);
504	    removal_outcome(tombstone_cid)
505	}
