507	/// Tauri command: resume a removal whose PDS account was already deleted.
508	///
509	/// Used when `confirm_identity_removal` deleted the account but the tombstone or wipe
510	/// failed: the single-use deletion token is already spent, so re-running `confirm`
511	/// would 401 at `deleteAccount`. `retire_and_wipe` is idempotent — if the tombstone
512	/// already landed (the DID's head is a tombstone), it does a wipe-only retry rather than
513	/// submitting a second, doomed operation; otherwise it completes the tombstone + wipe.
514	/// For a did:web there is no tombstone to retry at all, so the resume is the local wipe
515	/// alone: it cannot loop forever against a plc.directory that never hosted the DID.
516	#[tauri::command]
517	pub async fn tombstone_identity(
518	    state: tauri::State<'_, crate::oauth::AppState>,
519	    did: String,
520	) -> Result<RemovalOutcome, RemovalError> {
521	    let tombstone_cid = retire_and_wipe(state.pds_client(), &did).await?;
522	    clear_removal_pending_best_effort(&did);
523	    removal_outcome(tombstone_cid)
524	}
