527	///
528	/// Backs the launch-time reconciliation: if a removal deleted the PDS account but was
529	/// interrupted before the tombstone + wipe finished, the DID stays listed here so the UI
530	/// can resume it (idempotent `tombstone_identity`) instead of re-entering the request
531	/// flow. Infallible — any Keychain/decoding trouble reads as an empty list, so it can be
532	/// called unconditionally on every launch.
533	#[tauri::command]
534	pub fn list_pending_removals() -> Vec<String> {
535	    load_pending_removals()
536	}
