563	/// Resolve the PDS base URL for `did`: the stored token record first, then live
564	/// discovery. Used only to address the body-authed `deleteAccount` endpoint.
565	async fn resolve_pds_url(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
566	    if let Ok(Some(record)) = IdentityStore.load_oauth_tokens(did) {
567	        if !record.pds_url.is_empty() {
568	            return Ok(record.pds_url);
569	        }
570	    }
571	    let (pds_url, _doc) =
572	        pds_client
573	            .discover_pds(did)
574	            .await
575	            .map_err(|e| RemovalError::NetworkError {
576	                message: format!("could not resolve the identity's PDS: {e}"),
577	            })?;
578	    Ok(pds_url)
579	}
