82	    pub(crate) exp: u64,
83	    pub(crate) sub: String,
84	    pub(crate) aud: String,
85	}
86	
87	/// Decode a Bearer JWT's unverified payload into its `exp`/`sub`/`aud` claims.
88	///
89	/// The signature is NOT checked — the claims are only used for session-lifecycle
90	/// decisions (expiry) and to bind a restored/rotated session to the DID and hosting
91	/// server it was issued for, never as authorization data.
92	pub(crate) fn bearer_jwt_claims(token: &str) -> Option<BearerJwtClaims> {
93	    let payload = token.split('.').nth(1)?;
94	    let bytes = URL_SAFE_NO_PAD.decode(payload).ok()?;
95	    serde_json::from_slice(&bytes).ok()
96	}
97	
98	/// Whether a JWT `aud` claim identifies the hosting server, accepting either the
99	/// server DID or the PDS URL (some issuers set the public URL as the audience).
100	pub(crate) fn audience_matches_server(audience: &str, server_did: &str, pds_url: &str) -> bool {
101	    audience == server_did || audience.trim_end_matches('/') == pds_url.trim_end_matches('/')
102	}
