104	/// Generate a fresh 32-byte canonical base64url nonce for a sovereign-session proof.
105	pub(crate) fn fresh_nonce() -> String {
106	    let mut nonce_bytes = [0u8; NONCE_BYTES];
107	    OsRng.fill_bytes(&mut nonce_bytes);
108	    URL_SAFE_NO_PAD.encode(nonce_bytes)
109	}
