111	pub(crate) fn unix_timestamp() -> Result<i64, SovereignLoginError> {
112	    let seconds = SystemTime::now()
113	        .duration_since(UNIX_EPOCH)
114	        .map_err(|e| SovereignLoginError::InvalidResponse {
115	            message: format!("system clock is before Unix epoch: {e}"),
116	        })?
117	        .as_secs();
118	    i64::try_from(seconds).map_err(|_| SovereignLoginError::InvalidResponse {
119	        message: "system timestamp exceeds supported range".into(),
120	    })
121	}
