123	fn map_store_error(error: IdentityStoreError) -> SovereignLoginError {
124	    match error {
125	        IdentityStoreError::IdentityNotFound => SovereignLoginError::IdentityNotFound,
126	        IdentityStoreError::KeychainError { message } => {
127	            SovereignLoginError::KeychainFailure { message }
128	        }
129	        other => SovereignLoginError::KeychainFailure {
130	            message: other.to_string(),
131	        },
132	    }
133	}
134	
135	fn map_discovery_error(error: PdsClientError) -> SovereignLoginError {
136	    match error {
137	        PdsClientError::DidNotFound | PdsClientError::InvalidResponse { .. } => {
138	            SovereignLoginError::UnsupportedHost
139	        }
140	        PdsClientError::PdsUnreachable { reason } => {
141	            SovereignLoginError::TransportFailure { message: reason }
142	        }
143	        PdsClientError::NetworkError { message } => {
144	            SovereignLoginError::TransportFailure { message }
145	        }
146	        other => SovereignLoginError::TransportFailure {
147	            message: other.to_string(),
148	        },
149	    }
150	}
151	
152	fn pds_url_is_safe(url: &str) -> bool {
153	    let Ok(url) = url::Url::parse(url) else {
154	        return false;
155	    };
156	    url.scheme() == "https"
157	        || (url.scheme() == "http"
158	            && matches!(
159	                url.host_str(),
160	                Some("localhost") | Some("127.0.0.1") | Some("::1") | Some("[::1]")
161	            ))
162	}
