164	/// Mint and persist a full-access session for one managed DID.
165	#[tauri::command]
166	pub async fn sovereign_login(
167	    state: tauri::State<'_, AppState>,
168	    did: String,
169	) -> Result<SovereignLoginResult, SovereignLoginError> {
170	    let nonce = fresh_nonce();
171	    sovereign_login_impl(
172	        state.pds_client(),
173	        &IdentityStore,
174	        &did,
175	        unix_timestamp()?,
176	        &nonce,
177	    )
178	    .await
179	}
