181	pub(crate) async fn sovereign_login_impl(
182	    pds_client: &PdsClient,
183	    store: &IdentityStore,
184	    did: &str,
185	    timestamp: i64,
186	    nonce: &str,
187	) -> Result<SovereignLoginResult, SovereignLoginError> {
188	    let decoded_nonce = URL_SAFE_NO_PAD.decode(nonce).ok();
189	    if decoded_nonce.as_deref().map(<[u8]>::len) != Some(NONCE_BYTES)
190	        || decoded_nonce
191	            .as_deref()
192	            .is_some_and(|bytes| URL_SAFE_NO_PAD.encode(bytes) != nonce)
193	    {
194	        return Err(SovereignLoginError::InvalidResponse {
195	            message: "nonce must be 32 canonical base64url bytes".into(),
196	        });
197	    }
198	
199	    // Resolve the key before any request to the hosting PDS. This both enforces
200	    // managed-DID membership and guarantees the selected DID's key is the signer.
201	    let device_key = store
202	        .get_or_create_device_key(did)
203	        .map_err(map_store_error)?;
204	    let signer = crate::identity_store::per_did_sign_closure(did).map_err(|error| match error {
205	        PerDidSignError::DeviceKeyNotFound { message }
206	        | PerDidSignError::SigningSetupFailed { message } => {
207	            SovereignLoginError::SigningFailed { message }
208	        }
209	    })?;
210	
211	    let (pds_url, did_doc) = pds_client
212	        .discover_pds(did)
213	        .await
214	        .map_err(map_discovery_error)?;
215	    if did_doc.did != did {
216	        return Err(SovereignLoginError::DidMismatch);
217	    }
218	    if !pds_url_is_safe(&pds_url) {
219	        return Err(SovereignLoginError::UnsupportedHost);
220	    }
221	    let server = pds_client
222	        .describe_server(&pds_url)
223	        .await
224	        .map_err(map_discovery_error)?;
225	    if !server.did.starts_with("did:") || server.did.chars().any(char::is_whitespace) {
226	        return Err(SovereignLoginError::ServerMismatch);
227	    }
228	
229	    let envelope = crypto::encode_sovereign_session_envelope(
230	        &server.did,
231	        did,
232	        &device_key.key_id,
233	        timestamp,
234	        nonce,
235	    );
236	    let signature = signer(&envelope).map_err(|e| SovereignLoginError::SigningFailed {
237	        message: e.to_string(),
238	    })?;
239	    let request = SovereignSessionRequest {
240	        did,
241	        signing_key: &device_key.key_id,
242	        timestamp,
243	        nonce,
244	        signature: URL_SAFE_NO_PAD.encode(signature),
245	    };
246	
247	    let url = format!(
248	        "{}{}",
249	        pds_url.trim_end_matches('/'),
250	        crypto::SOVEREIGN_SESSION_PATH
251	    );
252	    let response = pds_client
253	        .client()
254	        .post(url)
255	        .json(&request)
256	        .send()
257	        .await
258	        .map_err(|e| SovereignLoginError::TransportFailure {
259	            message: e.to_string(),
260	        })?;
261	    let status = response.status();
262	    if !status.is_success() {
263	        return Err(match status.as_u16() {
264	            401 | 403 => SovereignLoginError::AuthorizationFailed,
265	            404 | 405 => SovereignLoginError::UnsupportedHost,
266	            429 => SovereignLoginError::RateLimited {
267	                retry_after: response
268	                    .headers()
269	                    .get(reqwest::header::RETRY_AFTER)
270	                    .and_then(|value| value.to_str().ok())
271	                    .map(str::to_string),
272	            },
273	            status => SovereignLoginError::ServerFailure { status },
274	        });
275	    }
276	
277	    let response: SovereignSessionResponse =
278	        response
279	            .json()
280	            .await
281	            .map_err(|e| SovereignLoginError::InvalidResponse {
282	                message: e.to_string(),
283	            })?;
284	    if response.did != did {
285	        return Err(SovereignLoginError::DidMismatch);
286	    }
287	    let access_claims = bearer_jwt_claims(&response.access_jwt).ok_or_else(|| {
288	        SovereignLoginError::InvalidResponse {
289	            message: "accessJwt is missing valid exp, sub, or aud claims".into(),
290	        }
291	    })?;
292	    let refresh_claims = bearer_jwt_claims(&response.refresh_jwt).ok_or_else(|| {
293	        SovereignLoginError::InvalidResponse {
294	            message: "refreshJwt is missing valid exp, sub, or aud claims".into(),
295	        }
296	    })?;
297	    if access_claims.sub != did || refresh_claims.sub != did {
298	        return Err(SovereignLoginError::DidMismatch);
299	    }
300	    if !audience_matches_server(&access_claims.aud, &server.did, &pds_url)
301	        || !audience_matches_server(&refresh_claims.aud, &server.did, &pds_url)
302	    {
303	        return Err(SovereignLoginError::ServerMismatch);
304	    }
305	    let access_expires_at = access_claims.exp;
306	    let refresh_expires_at = refresh_claims.exp;
307	    let stored_at = u64::try_from(timestamp).map_err(|_| SovereignLoginError::InvalidResponse {
308	        message: "negative timestamp cannot be persisted".into(),
309	    })?;
310	    let record = SovereignTokenRecord {
311	        version: SovereignTokenRecord::VERSION,
312	        access_jwt: response.access_jwt,
313	        refresh_jwt: response.refresh_jwt,
314	        pds_url: pds_url.clone(),
315	        server_did: server.did,
316	        access_expires_at: Some(access_expires_at),
317	        refresh_expires_at: Some(refresh_expires_at),
318	        stored_at,
319	    };
320	    store
321	        .store_oauth_tokens(did, &record)
322	        .map_err(map_store_error)?;
323	
324	    Ok(SovereignLoginResult {
325	        did: did.into(),
326	        pds_url,
327	        access_expires_at,
328	        refresh_expires_at,
329	    })
330	}
331	
332	/// Restore a selected DID's persisted full-access session as an authenticated XRPC client.
333	pub fn stored_bearer_client(did: &str) -> Result<Option<OAuthClient>, SovereignLoginError> {
334	    let Some(record) = IdentityStore
335	        .load_oauth_tokens(did)
336	        .map_err(map_store_error)?
337	    else {
338	        return Ok(None);
339	    };
340	    let access = bearer_jwt_claims(&record.access_jwt).ok_or_else(|| {
341	        SovereignLoginError::InvalidResponse {
342	            message: "stored accessJwt is malformed".into(),
343	        }
344	    })?;
345	    let refresh = bearer_jwt_claims(&record.refresh_jwt).ok_or_else(|| {
346	        SovereignLoginError::InvalidResponse {
347	            message: "stored refreshJwt is malformed".into(),
348	        }
349	    })?;
350	    if access.sub != did || refresh.sub != did {
351	        return Err(SovereignLoginError::DidMismatch);
352	    }
353	    if !audience_matches_server(&access.aud, &record.server_did, &record.pds_url)
354	        || !audience_matches_server(&refresh.aud, &record.server_did, &record.pds_url)
355	    {
356	        return Err(SovereignLoginError::ServerMismatch);
357	    }
358	    OAuthClient::new_bearer(record.access_jwt, record.refresh_jwt, record.pds_url)
359	        .map(Some)
360	        .map_err(|e| SovereignLoginError::KeychainFailure {
361	            message: e.to_string(),
362	        })
363	}
