167	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
168	    {
169	        let key = format!("consent:{}", query.request_id);
170	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
171	        if let Some(last) = tracker.get(&key) {
172	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
173	                return (
174	                    StatusCode::TOO_MANY_REQUESTS,
175	                    Json(StatusResponse {
176	                        status: "slow_down",
177	                    }),
178	                )
